);

const CheckListPage: React.FC<CheckListPageProps> = ({ view, currentUser }) => {
    const isCheckIn = view === 'checkin';
    const isCheckOut = view === 'checkout';
    const isMaintenance = view === 'manutencao';

    const [entries, setEntries] = useState<ChecklistEntry[]>([]);
    const [isModalOpen, setModalOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');

    const loadData = async () => {
        setIsLoading(true);
        const data = await dataService.getAll<ChecklistEntry>('checklist_entries', currentUser.id, currentUser.profileId === 'p1');
        setEntries(data);
        setIsLoading(false);
    };

    useEffect(() => { loadData(); }, [currentUser, view]);

    const filteredEntries = useMemo(() => {
        let filtered = entries.filter(e => e.type === view);
        if (searchTerm) filtered = filtered.filter(e => e.project.toLowerCase().includes(searchTerm.toLowerCase()));
        return filtered.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    }, [entries, view, searchTerm]);

    const handleNew = () => {
        setModalOpen(true);
    };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
                <div>
                    <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                        <ClipboardCheckIcon className="w-8 h-8 text-indigo-600" />
                        {isCheckIn ? 'Check-In de Obra' : isCheckOut ? 'Check-Out de Obra' : 'Manutenção'}
                    </h2>
                </div>
                <button onClick={handleNew} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 shadow-md font-bold uppercase text-xs">
                    <PlusIcon className="w-5 h-5" /> Novo Registro
                </button>
            </div>

            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden border border-gray-100 dark:border-gray-700">
                <div className="p-4 border-b border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
                    <input 
                        type="text" 
                        placeholder="Buscar projeto..." 
                        value={searchTerm} 
                        onChange={e => setSearchTerm(e.target.value)}
                        className="w-full sm:w-64 rounded-md border-gray-300 dark:border-gray-600 p-2 text-sm"
                    />
                </div>
                <table className="min-w-full text-left text-sm">
                    <thead className="bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-200 uppercase text-[10px] font-black">
                        <tr>
                            <th className="px-6 py-3">Data</th>
                            <th className="px-6 py-3">Projeto / Cliente</th>
                            <th className="px-6 py-3">Responsável</th>
                            <th className="px-6 py-3">Status</th>
                            <th className="px-6 py-3 text-right">Ações</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                        {filteredEntries.map(entry => (
                            <tr key={entry.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                <td className="px-6 py-4">{new Date(entry.date).toLocaleDateString('pt-BR', {timeZone: 'UTC'})}</td>
                                <td className="px-6 py-4 font-bold">{entry.project}</td>
                                <td className="px-6 py-4">{entry.responsible}</td>
                                <td className="px-6 py-4">
                                    <span className={`px-2 py-0.5 rounded text-[9px] font-black uppercase ${entry.status === 'Efetivado' ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-600'}`}>
                                        {entry.status}
                                    </span>
                                </td>
                                <td className="px-6 py-4 text-right">
                                    <button className="text-gray-400 hover:text-indigo-600 mx-1"><EditIcon className="w-4 h-4" /></button>
                                    <button className="text-gray-400 hover:text-red-600 mx-1"><TrashIcon className="w-4 h-4" /></button>
                                </td>
                            </tr>
                        ))}
                        {filteredEntries.length === 0 && (
                            <tr><td colSpan={5} className="px-6 py-12 text-center text-gray-400">Nenhum registro encontrado.</td></tr>
                        )}
                    </tbody>
                </table>
            </div>

            {isModalOpen && (
                <Modal title="Novo Registro" onClose={() => setModalOpen(false)}>
