};

export default CheckListPage;

import React, { useState, useEffect, useMemo } from 'react';
import { CubeIcon, ArrowUpIcon, ArrowDownIcon, TrashIcon, PhotographIcon, ShoppingCartIcon, AddIcon, EditIcon, XCircleIcon, CheckCircleIcon, PlusIcon } from '../assets/icons';
import Modal from '../components/Modal';
import DashboardCard from '../components/DashboardCard';
import type { StockItem, StockMovement, StockMovementType, EstoquePageProps, PurchaseRequest } from '../types';
import { dataService } from '../services/dataService';

type DashboardTab = 'lista' | 'movimentacoes';

const EstoquePage: React.FC<EstoquePageProps> = ({ view, setCurrentPage, currentUser }) => {
    const [items, setItems] = useState<StockItem[]>([]);
    const [movements, setMovements] = useState<StockMovement[]>([]);
    const [purchaseRequests, setPurchaseRequests] = useState<PurchaseRequest[]>([]);

    const [dashboardTab, setDashboardTab] = useState<DashboardTab>('lista');
    const [isLoading, setIsLoading] = useState(true);
    const [showAddForm, setShowAddForm] = useState(false);
    const [newItem, setNewItem] = useState<Partial<StockItem>>({ name: '', quantity: 0, minQuantity: 5, unit: 'un', description: '', image: '', averagePrice: 0 });

    const loadAllData = async () => {
        setIsLoading(true);
        try {
            const loadedItems = await dataService.getAll<StockItem>('stock_items');
            setItems((loadedItems || []).sort((a, b) => a.name.localeCompare(b.name)));

            const loadedMovements = await dataService.getAll<StockMovement>('stock_movements');
            setMovements((loadedMovements || []).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));

            const loadedRequests = await dataService.getAll<PurchaseRequest>('purchase_requests');
            setPurchaseRequests(loadedRequests || []);
        } catch (error) {
            console.error("Erro ao carregar estoque:", error);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        loadAllData();
    }, [currentUser, view]);

    const metrics = useMemo(() => {
        const totalItems = items.length;
        const lowStockItems = items.filter(i => i.quantity <= i.minQuantity).length;
        const totalStockValue = items.reduce((acc, i) => acc + (i.quantity * (i.averagePrice || 0)), 0);
        return { totalItems, lowStockItems, totalStockValue };
    }, [items]);

    const formatCurrency = (val: number) => {
        return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);
    };

    const handleSaveItem = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newItem.name) return;
        const item: StockItem = {
            id: `prod-${Date.now()}`,
            name: newItem.name || '',
            quantity: Number(newItem.quantity) || 0,
            minQuantity: Number(newItem.minQuantity) || 0,
            unit: newItem.unit || 'un',
            description: newItem.description,
            image: newItem.image,
            averagePrice: Number(newItem.averagePrice) || 0,
        };
        await dataService.save('stock_items', item);
        await loadAllData();
        setShowAddForm(false);
        setNewItem({ name: '', quantity: 0, minQuantity: 5, unit: 'un', description: '', image: '', averagePrice: 0 });
    };

    if (view === 'cadastro') {
        return (
            <div className="space-y-6">
                <div className="flex justify-between items-center bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
                    <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                        <CubeIcon className="w-8 h-8 text-indigo-600" />
                        Cadastro de Produtos
                    </h2>
                    <button onClick={() => setShowAddForm(!showAddForm)} className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 font-bold text-xs uppercase">
                        {showAddForm ? 'Cancelar' : 'Novo Produto'}
                    </button>
                </div>
                {showAddForm && (
                    <div className="p-6 bg-white dark:bg-gray-800 rounded-xl shadow-lg border border-gray-100 dark:border-gray-700">
                        <form onSubmit={handleSaveItem} className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Nome do Produto</label>
                                <input required type="text" value={newItem.name} onChange={e => setNewItem({...newItem, name: e.target.value})} className="w-full rounded-md border-gray-300 p-2 text-sm" />
                            </div>
                            <div className="grid grid-cols-2 gap-2">
                                <div>
                                    <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Qtd Inicial</label>
                                    <input type="number" value={newItem.quantity} onChange={e => setNewItem({...newItem, quantity: Number(e.target.value)})} className="w-full rounded-md border-gray-300 p-2 text-sm" />
                                </div>
                                <div>
                                    <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Unidade</label>
                                    <input type="text" value={newItem.unit} onChange={e => setNewItem({...newItem, unit: e.target.value})} className="w-full rounded-md border-gray-300 p-2 text-sm" />
                                </div>
                            </div>
                            <div className="md:col-span-2 pt-4">
                                <button type="submit" className="w-full py-2 bg-green-600 text-white rounded-md font-bold uppercase text-xs">Salvar Produto</button>
                            </div>
                        </form>
                    </div>
                )}
                <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden">
                    <table className="min-w-full text-left text-sm">
                        <thead className="bg-gray-100 dark:bg-gray-700 uppercase text-[10px] font-black">
                            <tr><th className="px-6 py-3">Produto</th><th className="px-6 py-3 text-center">Unid.</th><th className="px-6 py-3 text-center">Estoque</th><th className="px-6 py-3 text-right">Ações</th></tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                            {items.map(item => (
                                <tr key={item.id}>
                                    <td className="px-6 py-4 font-bold">{item.name}</td>
                                    <td className="px-6 py-4 text-center">{item.unit}</td>
                                    <td className="px-6 py-4 text-center font-black">{item.quantity}</td>
                                    <td className="px-6 py-4 text-right">
                                        <button className="text-gray-400 hover:text-red-600"><TrashIcon className="w-4 h-4" /></button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <DashboardCard title="Total de Itens" value={metrics.totalItems.toString()} icon={CubeIcon} color="bg-blue-500" />
                <DashboardCard title="Estoque Baixo" value={metrics.lowStockItems.toString()} icon={ShoppingCartIcon} color={metrics.lowStockItems > 0 ? "bg-red-500" : "bg-green-500"} />
                <DashboardCard title="Valor Total" value={formatCurrency(metrics.totalStockValue)} icon={CubeIcon} color="bg-purple-500" />
            </div>
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden border border-gray-100">
                <div className="p-4 border-b border-gray-200 flex gap-4 bg-gray-50">
                    <button onClick={() => setDashboardTab('lista')} className={`text-xs font-black uppercase ${dashboardTab === 'lista' ? 'text-indigo-600 border-b-2 border-indigo-600' : 'text-gray-400'}`}>Estoque Atual</button>
                    <button onClick={() => setDashboardTab('movimentacoes')} className={`text-xs font-black uppercase ${dashboardTab === 'movimentacoes' ? 'text-indigo-600 border-b-2 border-indigo-600' : 'text-gray-400'}`}>Lançamentos</button>
                </div>
                {dashboardTab === 'lista' ? (
                    <table className="min-w-full text-left text-sm">
                        <thead className="bg-gray-100 text-gray-500 uppercase text-[10px] font-black">
                            <tr><th className="px-6 py-3">Item</th><th className="px-6 py-3 text-center">Saldo</th><th className="px-6 py-3 text-center">V. Unit.</th><th className="px-6 py-3 text-right">Total</th></tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200">
                            {items.map(item => (
                                <tr key={item.id} className="hover:bg-gray-50">
                                    <td className="px-6 py-4 font-bold">{item.name}</td>
                                    <td className="px-6 py-4 text-center">{item.quantity}</td>
                                    <td className="px-6 py-4 text-center">{formatCurrency(item.averagePrice || 0)}</td>
                                    <td className="px-6 py-4 text-right font-medium">{formatCurrency(item.quantity * (item.averagePrice || 0))}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                ) : (
                    <table className="min-w-full text-left text-sm">
                        <thead className="bg-gray-100 text-gray-500 uppercase text-[10px] font-black">
                            <tr><th className="px-6 py-3">Data</th><th className="px-6 py-3">Tipo</th><th className="px-6 py-3">Item</th><th className="px-6 py-3 text-center">Qtd</th></tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200">
                            {movements.map(mov => (
                                <tr key={mov.id}>
                                    <td className="px-6 py-4">{new Date(mov.date).toLocaleDateString('pt-BR')}</td>
                                    <td className="px-6 py-4">
                                        <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase ${mov.type === 'entrada' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>{mov.type}</span>
                                    </td>
                                    <td className="px-6 py-4 font-medium">{items.find(i => i.id === mov.itemId)?.name || 'Item Removido'}</td>
                                    <td className="px-6 py-4 text-center font-bold">{mov.quantity}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
