import { supabase } from '../supabaseClient'; 

/**
 * Interface para garantir o padrão de persistência do sistema.
 */
interface IDataService {
    getAll<T>(collection: string, userId?: string, isAdmin?: boolean): Promise<T[]>;
    save<T extends { id: string | number }>(collection: string, item: T): Promise<T>;
    delete(collection: string, id: string | number): Promise<boolean>;
}

/**
 * Implementação Pura Supabase.
 * Sem redundância local para assegurar que apenas dados em nuvem sejam consumidos.
 */
class SupabaseDataService implements IDataService {

    async getAll<T>(table: string, userId?: string, isAdmin?: boolean): Promise<T[]> {
        if (!supabase) {
            throw new Error(`[Supabase] Cliente não inicializado.`);
        }

        try {
            let query = supabase.from(table).select('*');

            // Simulação de filtro de dono se não for admin
            if (userId && !isAdmin) {
                query = query.eq('ownerId', userId);
            }

            const { data, error } = await query;

            if (error) {
                console.error(`[Supabase] Erro ao buscar dados em ${table}:`, error.message);
                throw error;
            }

            return (data || []) as T[];
        } catch (err: any) {
            console.error(`[Supabase] Falha na operação de leitura:`, err.message);
            throw err;
        }
    }

    async save<T extends { id: string | number }>(table: string, item: T): Promise<T> {
        if (!supabase) {
            throw new Error(`[Supabase] Cliente não inicializado.`);
        }

        const cleanItem = JSON.parse(JSON.stringify(item));

        try {
            const { error } = await supabase.from(table).upsert(cleanItem);

            if (error) {
                console.error(`[Supabase] Erro ao salvar dados em ${table}:`, error.message);
                throw error;
            }

            return cleanItem;
        } catch (err: any) {
            console.error(`[Supabase] Falha na operação de escrita:`, err.message);
            throw err;
        }
    }

    async delete(table: string, id: string | number): Promise<boolean> {
        if (!supabase) {
            throw new Error(`[Supabase] Cliente não inicializado.`);
        }

        try {
            const { error } = await supabase.from(table).delete().eq('id', id);
            if (error) throw error;
            return true;
        } catch (err: any) {
            console.error(`[Supabase] Erro ao excluir registro:`, err.message);
            throw err;
        }
    }
}

export const dataService = new SupabaseDataService();

/**
 * LIMPEZA DO BANCO DE DADOS LOCAL (LocalStorage)
 * Remove as chaves de dados para garantir o uso exclusivo do Supabase.
 */
const OBSOLETE_KEYS = [
    'orcamentos', 
    'financial_transactions', 
    'financial_categories', 
    'stock_items', 
    'stock_movements', 
    'purchase_requests', 
    'checklist_entries', 
    'expense_reports', 
    'system_users', 
    'system_profiles', 
    'sales_summary',
    'reembolso_config_km_value',
    'config_installation_value'
];

try {
    OBSOLETE_KEYS.forEach(key => {
        if (localStorage.getItem(key)) {
            localStorage.removeItem(key);
        }
    });
    console.info("[System] Banco de dados local limpo. Operando exclusivamente via Supabase.");
} catch (e) {
    // Ignora falhas silenciosamente
}

