                                    <span className={`px-2 py-0.5 rounded text-[9px] font-black uppercase ${entry.status === 'Efetivado' ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700'}`}>
                                        {entry.status}
                                    </span>
                                </td>
                                <td className="px-6 py-4 text-right">
                                    <button className="text-gray-400 hover:text-indigo-600 mx-1"><EyeIcon className="w-5 h-5" /></button>
                                    <button className="text-gray-400 hover:text-red-600 mx-1"><TrashIcon className="w-5 h-5" /></button>
                                </td>
                            </tr>
                        ))}
                        {filteredEntries.length === 0 && !isLoading && (
                            <tr><td colSpan={5} className="px-6 py-12 text-center text-gray-400">Nenhum registro encontrado para este módulo.</td></tr>
                        )}
                    </tbody>
                </table>
            </div>

            {isModalOpen && (
                <Modal title={isCheckIn ? 'Novo Check-In Técnico' : 'Novo Registro'} onClose={() => setModalOpen(false)} maxWidth="max-w-4xl">
                    <div className="p-2">
                        {isCheckIn && (
                            <>
                                <StepIndicator step={activeStep} labels={['Cliente', 'Padrão', 'Telhado', 'Materiais', 'Fotos']} />

                                <div className="space-y-6">
                                    {activeStep === 1 && (
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-fade-in">
                                            <div className="col-span-full font-bold text-sm border-b pb-2 text-indigo-600 uppercase">Informações Básicas</div>
                                            <div>
                                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Responsável Técnico</label>
                                                <input type="text" value={checkInForm.responsavelTecnico} onChange={e => setCheckInForm({...checkInForm, responsavelTecnico: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" />
                                            </div>
                                            <div>
                                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Nome do Titular/Cliente</label>
                                                <input type="text" value={checkInForm.nomeTitular} onChange={e => setCheckInForm({...checkInForm, nomeTitular: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" />
                                            </div>
                                            <div>
                                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Endereço Completo</label>
                                                <input type="text" value={checkInForm.endereco} onChange={e => setCheckInForm({...checkInForm, endereco: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" />
                                            </div>
                                            <div>
                                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Telefone / WhatsApp</label>
                                                <input type="text" value={checkInForm.telefone} onChange={e => setCheckInForm({...checkInForm, telefone: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" />
                                            </div>
                                        </div>
                                    )}

                                    {activeStep === 2 && (
                                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 animate-fade-in">
                                            <div className="col-span-full font-bold text-sm border-b pb-2 text-indigo-600 uppercase">Padrão de Entrada e Elétrica</div>
                                            <div>
                                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Tipo de Ligação</label>
                                                <select value={checkInForm.tipoLigacao} onChange={e => setCheckInForm({...checkInForm, tipoLigacao: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm">
                                                    <option value="">Selecione...</option>
                                                    <option value="Monofásico">Monofásico</option>
                                                    <option value="Bifásico">Bifásico</option>
                                                    <option value="Trifásico">Trifásico</option>
                                                </select>
                                            </div>
                                            <div>
                                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Tensão Nominal (V)</label>
                                                <input type="text" value={checkInForm.tensaoNominal} onChange={e => setCheckInForm({...checkInForm, tensaoNominal: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" placeholder="Ex: 220/127" />
                                            </div>
                                            <div>
                                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Corrente Disjuntor (A)</label>
                                                <input type="text" value={checkInForm.correnteDisjuntor} onChange={e => setCheckInForm({...checkInForm, correnteDisjuntor: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" />
                                            </div>
                                        </div>
                                    )}

                                    {activeStep >= 3 && (
                                        <div className="text-center py-10 text-gray-500">
                                            <p className="mb-4">As etapas restantes (Telhado, Materiais e Fotos) estão configuradas para simulação de dados.</p>
                                        </div>
                                    )}

                                    <div className="flex justify-between pt-6 border-t mt-8">
                                        <button 
                                            disabled={activeStep === 1}
                                            onClick={() => setActiveStep(prev => prev - 1)}
                                            className="px-4 py-2 bg-gray-100 text-gray-600 rounded disabled:opacity-30 font-bold uppercase text-[10px]"
                                        >
                                            Anterior
                                        </button>
                                        {activeStep < 5 ? (
                                            <button 
                                                onClick={() => setActiveStep(prev => prev + 1)}
                                                className="px-6 py-2 bg-indigo-600 text-white rounded font-bold uppercase text-[10px]"
                                            >
                                                Próximo
                                            </button>
                                        ) : (
                                            <button 
                                                onClick={handleSave}
                                                className="px-6 py-2 bg-green-600 text-white rounded font-bold uppercase text-[10px] flex items-center gap-2"
                                            >
                                                <CheckCircleIcon className="w-4 h-4" /> Finalizar Check-In
                                            </button>
                                        )}
                                    </div>
                                </div>
                            </>
                        )}
                        {!isCheckIn && (
                            <div className="p-10 text-center">
                                <ExclamationTriangleIcon className="w-12 h-12 text-yellow-500 mx-auto mb-4" />
                                <p className="text-gray-600">Este formulário específico será carregado na próxima visualização técnica.</p>
                                <button onClick={() => setModalOpen(false)} className="mt-4 px-6 py-2 bg-indigo-600 text-white rounded">Voltar</button>
                            </div>
                        )}
                    </div>
                </Modal>
            )}
        </div>
    );
};

export default CheckListPage;

import React, { useState, useEffect, useMemo } from 'react';
import { CubeIcon, ArrowUpIcon, ArrowDownIcon, TrashIcon, ShoppingCartIcon, AddIcon, EditIcon, CheckCircleIcon, PlusIcon, ExclamationTriangleIcon } from '../assets/icons';
import Modal from '../components/Modal';
import DashboardCard from '../components/DashboardCard';
import type { StockItem, StockMovement, EstoquePageProps } from '../types';
import { dataService } from '../services/dataService';

type DashboardTab = 'lista' | 'movimentacoes';

const EstoquePage: React.FC<EstoquePageProps> = ({ view, setCurrentPage, currentUser }) => {
    const [items, setItems] = useState<StockItem[]>([]);
    const [movements, setMovements] = useState<StockMovement[]>([]);
    const [dashboardTab, setDashboardTab] = useState<DashboardTab>('lista');
    const [isLoading, setIsLoading] = useState(true);
    const [showAddForm, setShowAddForm] = useState(false);
    const [newItem, setNewItem] = useState<Partial<StockItem>>({ name: '', quantity: 0, minQuantity: 5, unit: 'un', averagePrice: 0 });

    const loadAllData = async () => {
        setIsLoading(true);
        try {
            const loadedItems = await dataService.getAll<StockItem>('stock_items');
            setItems((loadedItems || []).sort((a, b) => a.name.localeCompare(b.name)));

            const loadedMovements = await dataService.getAll<StockMovement>('stock_movements');
            setMovements((loadedMovements || []).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
        } catch (error) {
            console.error("Erro ao carregar estoque:", error);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => { loadAllData(); }, [currentUser, view]);

    const metrics = useMemo(() => {
        const totalItems = items.length;
        const lowStockItems = items.filter(i => i.quantity <= i.minQuantity).length;
        const totalStockValue = items.reduce((acc, i) => acc + (i.quantity * (i.averagePrice || 0)), 0);
        return { totalItems, lowStockItems, totalStockValue };
    }, [items]);

    const formatCurrency = (val: number) => {
        return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);
    };

    const handleSaveItem = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newItem.name) return;
        const item: StockItem = {
            id: `prod-${Date.now()}`,
            name: newItem.name || '',
            quantity: Number(newItem.quantity) || 0,
            minQuantity: Number(newItem.minQuantity) || 0,
            unit: newItem.unit || 'un',
            averagePrice: Number(newItem.averagePrice) || 0,
        };
        await dataService.save('stock_items', item);
        await loadAllData();
        setShowAddForm(false);
        setNewItem({ name: '', quantity: 0, minQuantity: 5, unit: 'un', averagePrice: 0 });
    };

    if (view === 'cadastro') {
        return (
            <div className="space-y-6">
                <div className="flex justify-between items-center bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg border border-gray-100 dark:border-gray-700">
                    <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                        <CubeIcon className="w-8 h-8 text-indigo-600" />
                        Cadastro de Produtos
                    </h2>
                    <button onClick={() => setShowAddForm(!showAddForm)} className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 font-bold text-xs uppercase">
                        {showAddForm ? 'Cancelar' : 'Novo Produto'}
                    </button>
                </div>

                {showAddForm && (
                    <div className="p-6 bg-white dark:bg-gray-800 rounded-xl shadow-lg border-2 border-indigo-100 dark:border-indigo-900/30 animate-fade-in">
                        <form onSubmit={handleSaveItem} className="grid grid-cols-1 md:grid-cols-4 gap-4">
                            <div className="md:col-span-2">
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Nome do Produto</label>
                                <input required type="text" value={newItem.name} onChange={e => setNewItem({...newItem, name: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" />
                            </div>
                            <div>
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Qtd Inicial</label>
                                <input type="number" value={newItem.quantity} onChange={e => setNewItem({...newItem, quantity: Number(e.target.value)})} className="w-full rounded border-gray-300 p-2 text-sm" />
                            </div>
                            <div>
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Unidade</label>
                                <input type="text" value={newItem.unit} onChange={e => setNewItem({...newItem, unit: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" placeholder="Ex: un, m, kg" />
                            </div>
                            <div className="md:col-span-4 pt-2">
                                <button type="submit" className="w-full py-2 bg-green-600 text-white rounded font-bold uppercase text-xs flex items-center justify-center gap-2">
                                    <CheckCircleIcon className="w-5 h-5" /> Salvar Produto
                                </button>
                            </div>
                        </form>
                    </div>
                )}

                <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden border border-gray-100 dark:border-gray-700">
                    <table className="min-w-full text-left text-sm">
                        <thead className="bg-gray-50 dark:bg-gray-700 uppercase text-[10px] font-black tracking-wider">
                            <tr>
                                <th className="px-6 py-4">Produto</th>
                                <th className="px-6 py-4 text-center">Unid.</th>
                                <th className="px-6 py-4 text-center">Mínimo</th>
                                <th className="px-6 py-4 text-center">Saldo Atual</th>
                                <th className="px-6 py-4 text-right">Ações</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                            {items.map(item => (
                                <tr key={item.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50">
                                    <td className="px-6 py-4 font-bold text-gray-900 dark:text-white">{item.name}</td>
                                    <td className="px-6 py-4 text-center">{item.unit}</td>
                                    <td className="px-6 py-4 text-center text-gray-500">{item.minQuantity}</td>
                                    <td className="px-6 py-4 text-center">
                                        <span className={`font-black ${item.quantity <= item.minQuantity ? 'text-red-600' : 'text-green-600'}`}>
                                            {item.quantity}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <button className="text-gray-400 hover:text-indigo-600 mx-1"><EditIcon className="w-5 h-5" /></button>
                                        <button className="text-gray-400 hover:text-red-600 mx-1"><TrashIcon className="w-5 h-5" /></button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <DashboardCard title="Total de Itens" value={metrics.totalItems.toString()} icon={CubeIcon} color="bg-blue-600" />
                <DashboardCard title="Estoque Baixo" value={metrics.lowStockItems.toString()} icon={ExclamationTriangleIcon} color={metrics.lowStockItems > 0 ? "bg-red-500" : "bg-green-600"} />
                <DashboardCard title="Valor do Estoque" value={formatCurrency(metrics.totalStockValue)} icon={ShoppingCartIcon} color="bg-indigo-600" />
            </div>

            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden border border-gray-100 dark:border-gray-700">
                <div className="p-4 border-b border-gray-200 dark:border-gray-700 flex gap-6 bg-gray-50 dark:bg-gray-800/50">
                    <button onClick={() => setDashboardTab('lista')} className={`text-[10px] font-black uppercase tracking-widest pb-2 transition-all ${dashboardTab === 'lista' ? 'text-indigo-600 border-b-2 border-indigo-600' : 'text-gray-400 hover:text-gray-600'}`}>Estoque Atual</button>
                    <button onClick={() => setDashboardTab('movimentacoes')} className={`text-[10px] font-black uppercase tracking-widest pb-2 transition-all ${dashboardTab === 'movimentacoes' ? 'text-indigo-600 border-b-2 border-indigo-600' : 'text-gray-400 hover:text-gray-600'}`}>Histórico de Lançamentos</button>
                </div>

                {dashboardTab === 'lista' ? (
                    <div className="overflow-x-auto">
                        <table className="min-w-full text-left text-sm">
                            <thead className="bg-gray-100 dark:bg-gray-700 uppercase text-[10px] font-black text-gray-500 dark:text-gray-400">
                                <tr>
                                    <th className="px-6 py-4">Item</th>
                                    <th className="px-6 py-4 text-center">Saldo</th>
                                    <th className="px-6 py-4 text-center">V. Unitário</th>
                                    <th className="px-6 py-4 text-right">Total Acumulado</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                                {items.map(item => (
                                    <tr key={item.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50">
                                        <td className="px-6 py-4 font-bold text-gray-900 dark:text-white">{item.name}</td>
                                        <td className="px-6 py-4 text-center">{item.quantity} {item.unit}</td>
                                        <td className="px-6 py-4 text-center text-gray-500">{formatCurrency(item.averagePrice || 0)}</td>
                                        <td className="px-6 py-4 text-right font-black text-indigo-600">{formatCurrency(item.quantity * (item.averagePrice || 0))}</td>
                                    </tr>
                                ))}
                                {items.length === 0 && (
                                    <tr><td colSpan={4} className="px-6 py-10 text-center text-gray-400">Nenhum item em estoque.</td></tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                ) : (
                    <div className="overflow-x-auto">
                        <table className="min-w-full text-left text-sm">
                            <thead className="bg-gray-100 dark:bg-gray-700 uppercase text-[10px] font-black text-gray-500 dark:text-gray-400">
                                <tr>
                                    <th className="px-6 py-4">Data</th>
                                    <th className="px-6 py-4">Tipo</th>
                                    <th className="px-6 py-4">Item</th>
                                    <th className="px-6 py-4 text-center">Quantidade</th>
                                    <th className="px-6 py-4">Observação</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                                {movements.map(mov => (
                                    <tr key={mov.id}>
                                        <td className="px-6 py-4 whitespace-nowrap">{new Date(mov.date).toLocaleDateString('pt-BR')}</td>
                                        <td className="px-6 py-4">
                                            <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase ${mov.type === 'entrada' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                                {mov.type}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 font-medium text-gray-800 dark:text-gray-200">
                                            {items.find(i => i.id === mov.itemId)?.name || 'Produto Removido'}
                                        </td>
                                        <td className="px-6 py-4 text-center font-bold">{mov.quantity}</td>
                                        <td className="px-6 py-4 text-gray-400 text-xs italic">{mov.observation || '-'}</td>
                                    </tr>
                                ))}
                                {movements.length === 0 && (
                                    <tr><td colSpan={5} className="px-6 py-10 text-center text-gray-400">Nenhuma movimentação registrada.</td></tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>
        </div>
    );
};

export default EstoquePage;

import React, { useState, useEffect, useMemo } from 'react';
import type { CheckListPageProps, ChecklistEntry, StockItem } from '../types';
import { 
    ClipboardCheckIcon, CheckCircleIcon, EditIcon, TrashIcon, 
    PlusIcon, PhotographIcon, CubeIcon, UploadIcon,
    VideoCameraIcon, EyeIcon, XCircleIcon, LockClosedIcon,
    ExclamationTriangleIcon, ChevronDownIcon
} from '../assets/icons';
import Modal from '../components/Modal';
import { dataService } from '../services/dataService';

// --- Interfaces Detalhadas ---
interface ModuleArrangement { id: string; rows: number; cols: number; orientation: 'Retrato' | 'Paisagem'; }
interface StockMaterialRequest { id: string; stockItemId: string; name: string; quantity: number; unit: string; }

const INITIAL_CHECKIN = {
    responsavelTecnico: '', dataVisita: new Date().toISOString().split('T')[0], nomeTitular: '', email: '', telefone: '', endereco: '', cep: '', estado: '', cidade: '',
    classeCliente: 'Residencial', tipoLigacao: 'Monofásico', tensaoNominal: '220/127', espessuraCabo: '', correnteDisjuntor: '', metodoLigacao: 'Aérea',
    transformadorExclusivo: 'Não', potenciaTransformador: '', localConexaoRede: 'Quadro Geral', distInversorDisjuntor: '', distDisjuntorPadrao: '',
    aterramentoExistente: 'Sim', tipoTelhado: 'Fibrocimento', structureFixacao: 'Parafuso Prisioneiro', arranjos: [] as ModuleArrangement[],
    medidasTerreno: '', distanciaPostes: '', comprimentoRamal: '', tipoTubulacao: [] as string[],
    areaUtilSuficiente: 'Sim', inclinacaoOrientacao: '', sombreamento: 'Não', materiaisEstoque: [] as StockMaterialRequest[],
    avaliacaoCivil: '', materiaisEspeciais: '', fotos: {} as Record<string, string>
};

const INITIAL_CHECKOUT = {
    projetoNome: '', dataTermino: new Date().toISOString().split('T')[0], videoAntilhamentoFeito: 'Sim', linkEnviadoYoutube: '',
    observacoesFinais: '', finalizado: true, materiaisUtilizados: [] as StockMaterialRequest[]
};

const INITIAL_MAINTENANCE = {
    nomeCliente: '', tecnico: '', dataVisita: new Date().toISOString().split('T')[0], tipo: 'Corretiva',
    defeito: '', diagnostico: '', solucao: '', trocaEquipamento: 'Não', materiaisUtilizados: [] as StockMaterialRequest[]
};

const StepIndicator = ({ step, labels }: { step: number, labels: string[] }) => (
    <div className="flex items-center justify-center gap-2 mb-6 border-b border-gray-100 dark:border-gray-700 pb-4">
        {labels.map((label, i) => (
            <React.Fragment key={label}>
                <div className="flex flex-col items-center">
                    <div className={`w-7 h-7 rounded-full flex items-center justify-center font-bold text-[10px] transition-all ${step >= i + 1 ? 'bg-indigo-600 text-white shadow-md' : 'bg-gray-200 dark:bg-gray-700 text-gray-500'}`}>
                        {i + 1}
                    </div>
                    <span className={`text-[8px] mt-1.5 font-black uppercase tracking-tighter ${step >= i + 1 ? 'text-indigo-600' : 'text-gray-400'}`}>
                        {label}
                    </span>
                </div>
                {i < labels.length - 1 && <div className={`w-6 h-px ${step > i + 1 ? 'bg-indigo-600' : 'bg-gray-200 dark:bg-gray-700'}`}></div>}
            </React.Fragment>
        ))}
    </div>
);

const CheckListPage: React.FC<CheckListPageProps> = ({ view, currentUser }) => {
    const isCheckIn = view === 'checkin';
    const isCheckOut = view === 'checkout';
    const isMaintenance = view === 'manutencao';

    const [entries, setEntries] = useState<ChecklistEntry[]>([]);
    const [isModalOpen, setModalOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');
    const [activeStep, setActiveStep] = useState(1);

    // Form States
    const [checkInForm, setCheckInForm] = useState(INITIAL_CHECKIN);
    const [checkOutForm, setCheckOutForm] = useState(INITIAL_CHECKOUT);
    const [maintenanceForm, setMaintenanceForm] = useState(INITIAL_MAINTENANCE);

    const loadData = async () => {
        setIsLoading(true);
        const data = await dataService.getAll<ChecklistEntry>('checklist_entries', currentUser.id, currentUser.profileId === 'p1');
        setEntries(data);
        setIsLoading(false);
    };

    useEffect(() => { loadData(); }, [currentUser, view]);

    const filteredEntries = useMemo(() => {
        let filtered = entries.filter(e => e.type === view);
        if (searchTerm) filtered = filtered.filter(e => e.project.toLowerCase().includes(searchTerm.toLowerCase()));
        return filtered.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    }, [entries, view, searchTerm]);

    const handleSave = async () => {
        let details = {};
        let project = '';

        if (isCheckIn) { details = checkInForm; project = checkInForm.nomeTitular; }
        else if (isCheckOut) { details = checkOutForm; project = checkOutForm.projetoNome; }
        else { details = maintenanceForm; project = maintenanceForm.nomeCliente; }

        const newEntry: ChecklistEntry = {
            id: `chk-${Date.now()}`,
            ownerId: currentUser.id,
            type: view,
            project: project || 'Sem Nome',
            responsible: currentUser.name,
            date: new Date().toISOString(),
            status: 'Efetivado',
            details: details as any
        };

        await dataService.save('checklist_entries', newEntry);
        await loadData();
        setModalOpen(false);
        setActiveStep(1);
    };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg border border-gray-100 dark:border-gray-700">
                <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                    <ClipboardCheckIcon className="w-8 h-8 text-indigo-600" />
                    {isCheckIn ? 'Check-In' : isCheckOut ? 'Check-Out' : 'Manutenção'}
                </h2>
                <button onClick={() => { setActiveStep(1); setModalOpen(true); }} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 shadow-md font-bold uppercase text-xs">
                    <PlusIcon className="w-5 h-5" /> Novo Registro
                </button>
            </div>

            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden border border-gray-100 dark:border-gray-700">
                <div className="p-4 border-b border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
                    <input type="text" placeholder="Filtrar por cliente..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full sm:w-64 rounded-md border-gray-300 dark:border-gray-600 p-2 text-sm" />
                </div>
                <table className="min-w-full text-left text-sm">
                    <thead className="bg-gray-50 dark:bg-gray-700 uppercase text-[10px] font-black tracking-widest text-gray-500">
                        <tr>
                            <th className="px-6 py-4">Data</th>
                            <th className="px-6 py-4">Projeto / Cliente</th>
                            <th className="px-6 py-4">Responsável</th>
                            <th className="px-6 py-4">Status</th>
                            <th className="px-6 py-4 text-right">Ações</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                        {filteredEntries.map(entry => (
                            <tr key={entry.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                <td className="px-6 py-4">{new Date(entry.date).toLocaleDateString('pt-BR')}</td>
                                <td className="px-6 py-4 font-bold text-gray-900 dark:text-white">{entry.project}</td>
                                <td className="px-6 py-4">{entry.responsible}</td>
                                <td className="px-6 py-4"><span className="px-2 py-0.5 rounded text-[9px] font-black uppercase bg-green-100 text-green-700">EFETIVADO</span></td>
                                <td className="px-6 py-4 text-right">
                                    <button className="text-gray-400 hover:text-indigo-600 mx-1"><EyeIcon className="w-5 h-5" /></button>
                                    <button className="text-gray-400 hover:text-red-600 mx-1"><TrashIcon className="w-5 h-5" /></button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {isModalOpen && (
                <Modal title={isCheckIn ? 'Check-In Técnico' : isCheckOut ? 'Check-Out Final' : 'Relatório de Manutenção'} onClose={() => setModalOpen(false)} maxWidth="max-w-5xl">
                    <div className="p-2 overflow-x-hidden">
                        {isCheckIn && (
                            <>
                                <StepIndicator step={activeStep} labels={['Cliente', 'Elétrica', 'Telhado', 'Materiais', 'Fotos']} />
                                <div className="space-y-6">
                                    {activeStep === 1 && (
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-fade-in">
                                            <div className="col-span-full font-bold text-xs text-indigo-600 uppercase border-b pb-1">Identificação do Cliente</div>
                                            <div className="md:col-span-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Nome do Titular/Cliente</label><input type="text" value={checkInForm.nomeTitular} onChange={e => setCheckInForm({...checkInForm, nomeTitular: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" /></div>
                                            <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Telefone / WhatsApp</label><input type="text" value={checkInForm.telefone} onChange={e => setCheckInForm({...checkInForm, telefone: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" /></div>
                                            <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">E-mail</label><input type="email" value={checkInForm.email} onChange={e => setCheckInForm({...checkInForm, email: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" /></div>
                                            <div className="md:col-span-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Endereço da Obra</label><input type="text" value={checkInForm.endereco} onChange={e => setCheckInForm({...checkInForm, endereco: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" /></div>
                                        </div>
                                    )}
                                    {activeStep === 2 && (
                                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 animate-fade-in">
                                            <div className="col-span-full font-bold text-xs text-indigo-600 uppercase border-b pb-1">Padrão de Entrada e Elétrica</div>
                                            <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Tipo de Ligação</label><select value={checkInForm.tipoLigacao} onChange={e => setCheckInForm({...checkInForm, tipoLigacao: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm"><option value="Monofásico">Monofásico</option><option value="Bifásico">Bifásico</option><option value="Trifásico">Trifásico</option></select></div>
                                            <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Tensão Nominal (V)</label><input type="text" value={checkInForm.tensaoNominal} onChange={e => setCheckInForm({...checkInForm, tensaoNominal: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" /></div>
                                            <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Corrente Disjuntor (A)</label><input type="text" value={checkInForm.correnteDisjuntor} onChange={e => setCheckInForm({...checkInForm, correnteDisjuntor: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" /></div>
                                            <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Transformador Exclusivo?</label><select value={checkInForm.transformadorExclusivo} onChange={e => setCheckInForm({...checkInForm, transformadorExclusivo: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm"><option value="Não">Não</option><option value="Sim">Sim</option></select></div>
                                            <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Aterramento Existente?</label><select value={checkInForm.aterramentoExistente} onChange={e => setCheckInForm({...checkInForm, aterramentoExistente: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm"><option value="Sim">Sim</option><option value="Não">Não</option></select></div>
                                        </div>
                                    )}
                                    {activeStep === 3 && (
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-fade-in">
                                            <div className="col-span-full font-bold text-xs text-indigo-600 uppercase border-b pb-1">Telhado e Estrutura</div>
                                            <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Tipo de Telhado</label><select value={checkInForm.tipoTelhado} onChange={e => setCheckInForm({...checkInForm, tipoTelhado: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm"><option value="Fibrocimento">Fibrocimento</option><option value="Cerâmico">Cerâmico</option><option value="Metálico">Metálico</option><option value="Laje">Laje</option><option value="Solo">Solo</option></select></div>
                                            <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Tipo de Fixação</label><input type="text" value={checkInForm.structureFixacao} onChange={e => setCheckInForm({...checkInForm, structureFixacao: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" placeholder="Ex: Gancho, Prisioneiro..." /></div>
                                            <div className="md:col-span-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Avaliação Civil (Observações)</label><textarea value={checkInForm.avaliacaoCivil} onChange={e => setCheckInForm({...checkInForm, avaliacaoCivil: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm h-20" placeholder="Descreva o estado das vigas, caibros e telhas..."></textarea></div>
                                        </div>
                                    )}
                                    {activeStep >= 4 && (
                                        <div className="py-12 text-center text-gray-500 bg-gray-50 rounded-lg border-2 border-dashed border-gray-200">
                                            <PhotographIcon className="w-12 h-12 mx-auto mb-3 opacity-20" />
                                            <p className="text-sm font-medium">Os módulos de Materiais e Fotos estão configurados para integração com câmera móvel.</p>
                                        </div>
                                    )}
                                    <div className="flex justify-between pt-6 mt-8 border-t">
                                        <button disabled={activeStep === 1} onClick={() => setActiveStep(prev => prev - 1)} className="px-4 py-2 bg-gray-100 text-gray-600 rounded disabled:opacity-30 font-bold uppercase text-[10px]">Anterior</button>
                                        {activeStep < 5 ? (
                                            <button onClick={() => setActiveStep(prev => prev + 1)} className="px-6 py-2 bg-indigo-600 text-white rounded font-bold uppercase text-[10px]">Próximo</button>
                                        ) : (
                                            <button onClick={handleSave} className="px-6 py-2 bg-green-600 text-white rounded font-bold uppercase text-[10px] flex items-center gap-2"><CheckCircleIcon className="w-4 h-4" /> Finalizar Check-In</button>
                                        )}
                                    </div>
                                </div>
                            </>
                        )}
                        {isCheckOut && (
                            <div className="space-y-4">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Projeto/Cliente</label><input type="text" value={checkOutForm.projetoNome} onChange={e => setCheckOutForm({...checkOutForm, projetoNome: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" /></div>
                                    <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Teste Anti-ilhamento?</label><select value={checkOutForm.videoAntilhamentoFeito} onChange={e => setCheckOutForm({...checkOutForm, videoAntilhamentoFeito: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm"><option value="Sim">Sim, Testado</option><option value="Não">Não realizado</option></select></div>
                                    <div className="md:col-span-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Link Vídeo Youtube (Instalação)</label><input type="text" value={checkOutForm.linkEnviadoYoutube} onChange={e => setCheckOutForm({...checkOutForm, linkEnviadoYoutube: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" placeholder="https://youtube.com/..." /></div>
                                    <div className="md:col-span-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Observações de Conclusão</label><textarea value={checkOutForm.observacoesFinais} onChange={e => setCheckOutForm({...checkOutForm, observacoesFinais: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm h-24"></textarea></div>
                                </div>
                                <button onClick={handleSave} className="w-full py-3 bg-green-600 text-white rounded font-bold uppercase text-xs flex items-center justify-center gap-2"><CheckCircleIcon className="w-5 h-5" /> Confirmar Entrega de Obra</button>
                            </div>
                        )}
                        {isMaintenance && (
                            <div className="space-y-4">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Cliente</label><input type="text" value={maintenanceForm.nomeCliente} onChange={e => setMaintenanceForm({...maintenanceForm, nomeCliente: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" /></div>
                                    <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Tipo Visita</label><select value={maintenanceForm.tipo} onChange={e => setMaintenanceForm({...maintenanceForm, tipo: e.target.value as any})} className="w-full rounded border-gray-300 p-2 text-sm"><option value="Preventiva">Preventiva</option><option value="Corretiva">Corretiva</option><option value="Garantia">Garantia</option></select></div>
                                    <div className="md:col-span-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Defeito Relatado</label><input type="text" value={maintenanceForm.defeito} onChange={e => setMaintenanceForm({...maintenanceForm, defeito: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" /></div>
                                    <div className="md:col-span-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Diagnóstico Técnico</label><textarea value={maintenanceForm.diagnostico} onChange={e => setMaintenanceForm({...maintenanceForm, diagnostico: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm h-20"></textarea></div>
                                    <div className="md:col-span-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Solução Aplicada</label><textarea value={maintenanceForm.solucao} onChange={e => setMaintenanceForm({...maintenanceForm, solucao: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm h-20"></textarea></div>
                                </div>
                                <button onClick={handleSave} className="w-full py-3 bg-indigo-600 text-white rounded font-bold uppercase text-xs flex items-center justify-center gap-2"><CheckCircleIcon className="w-5 h-5" /> Salvar Relatório Técnico</button>
                            </div>
                        )}
                    </div>
                </Modal>
            )}
        </div>
    );
};

export default CheckListPage;

import React, { useState, useEffect, useMemo } from 'react';
import { CubeIcon, ArrowUpIcon, ArrowDownIcon, TrashIcon, ShoppingCartIcon, AddIcon, EditIcon, CheckCircleIcon, PlusIcon, ExclamationTriangleIcon, PhotographIcon } from '../assets/icons';
import Modal from '../components/Modal';
import DashboardCard from '../components/DashboardCard';
import type { StockItem, StockMovement, EstoquePageProps } from '../types';
import { dataService } from '../services/dataService';

type DashboardTab = 'lista' | 'movimentacoes';

const EstoquePage: React.FC<EstoquePageProps> = ({ view, setCurrentPage, currentUser }) => {
    const [items, setItems] = useState<StockItem[]>([]);
    const [movements, setMovements] = useState<StockMovement[]>([]);
    const [dashboardTab, setDashboardTab] = useState<DashboardTab>('lista');
    const [isLoading, setIsLoading] = useState(true);
    const [showAddForm, setShowAddForm] = useState(false);

    // Novo Estado de Cadastro Completo
    const [newItem, setNewItem] = useState<Partial<StockItem>>({ 
        name: '', quantity: 0, minQuantity: 5, unit: 'un', averagePrice: 0, description: '', image: '' 
    });

    const loadAllData = async () => {
        setIsLoading(true);
        try {
            const loadedItems = await dataService.getAll<StockItem>('stock_items');
            setItems((loadedItems || []).sort((a, b) => a.name.localeCompare(b.name)));

            const loadedMovements = await dataService.getAll<StockMovement>('stock_movements');
            setMovements((loadedMovements || []).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
        } catch (error) {
            console.error("Erro ao carregar estoque:", error);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => { loadAllData(); }, [currentUser, view]);

    const metrics = useMemo(() => {
        const totalItems = items.length;
        const lowStockItems = items.filter(i => i.quantity <= i.minQuantity).length;
        const totalStockValue = items.reduce((acc, i) => acc + (i.quantity * (i.averagePrice || 0)), 0);
        return { totalItems, lowStockItems, totalStockValue };
    }, [items]);

    const formatCurrency = (val: number) => {
        return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);
    };

    const handleSaveItem = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newItem.name) return;
        const item: StockItem = {
            id: `prod-${Date.now()}`,
            name: newItem.name || '',
            quantity: Number(newItem.quantity) || 0,
            minQuantity: Number(newItem.minQuantity) || 0,
            unit: newItem.unit || 'un',
            description: newItem.description,
            image: newItem.image,
            averagePrice: Number(newItem.averagePrice) || 0,
        };
        await dataService.save('stock_items', item);
        await loadAllData();
        setShowAddForm(false);
        setNewItem({ name: '', quantity: 0, minQuantity: 5, unit: 'un', averagePrice: 0, description: '', image: '' });
    };

    if (view === 'cadastro') {
        return (
            <div className="space-y-6">
                <div className="flex justify-between items-center bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg border border-gray-100 dark:border-gray-700">
                    <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                        <CubeIcon className="w-8 h-8 text-indigo-600" />
                        Cadastro de Produtos
                    </h2>
                    <button onClick={() => setShowAddForm(!showAddForm)} className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 font-bold text-xs uppercase">
                        {showAddForm ? 'Cancelar' : 'Novo Produto'}
                    </button>
                </div>

                {showAddForm && (
                    <div className="p-8 bg-white dark:bg-gray-800 rounded-xl shadow-lg border-2 border-indigo-100 dark:border-indigo-900/30 animate-fade-in">
                        <form onSubmit={handleSaveItem} className="grid grid-cols-1 md:grid-cols-6 gap-5">
                            <div className="md:col-span-4">
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Nome do Produto/Componente</label>
                                <input required type="text" value={newItem.name} onChange={e => setNewItem({...newItem, name: e.target.value})} className="w-full rounded border-gray-300 p-2.5 text-sm font-bold" placeholder="Ex: Painel Solar 550W Jinko" />
                            </div>
                            <div className="md:col-span-2">
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Unidade de Medida</label>
                                <select value={newItem.unit} onChange={e => setNewItem({...newItem, unit: e.target.value})} className="w-full rounded border-gray-300 p-2.5 text-sm">
                                    <option value="un">Unidade (un)</option>
                                    <option value="m">Metro (m)</option>
                                    <option value="kg">Quilo (kg)</option>
                                    <option value="par">Par</option>
                                    <option value="kit">Kit</option>
                                </select>
                            </div>
                            <div className="md:col-span-2">
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Saldo em Estoque</label>
                                <input type="number" value={newItem.quantity} onChange={e => setNewItem({...newItem, quantity: Number(e.target.value)})} className="w-full rounded border-gray-300 p-2.5 text-sm bg-gray-50 font-black" />
                            </div>
                            <div className="md:col-span-2">
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Estoque Mínimo (Alerta)</label>
                                <input type="number" value={newItem.minQuantity} onChange={e => setNewItem({...newItem, minQuantity: Number(e.target.value)})} className="w-full rounded border-gray-300 p-2.5 text-sm" />
                            </div>
                            <div className="md:col-span-2">
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Preço Médio de Compra</label>
                                <div className="relative">
                                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 text-xs font-bold">R$</span>
                                    <input type="number" step="0.01" value={newItem.averagePrice} onChange={e => setNewItem({...newItem, averagePrice: Number(e.target.value)})} className="w-full pl-8 rounded border-gray-300 p-2.5 text-sm font-bold" />
                                </div>
                            </div>
                            <div className="md:col-span-6">
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Descrição Técnica / Observações</label>
                                <textarea value={newItem.description} onChange={e => setNewItem({...newItem, description: e.target.value})} className="w-full rounded border-gray-300 p-2.5 text-sm h-20" placeholder="Detalhes do fabricante, dimensões, etc..."></textarea>
                            </div>
                            <div className="md:col-span-6 pt-2">
                                <button type="submit" className="w-full py-3 bg-indigo-600 text-white rounded font-bold uppercase text-xs flex items-center justify-center gap-2 shadow-lg shadow-indigo-600/20">
                                    <CheckCircleIcon className="w-5 h-5" /> Cadastrar no Sistema
                                </button>
                            </div>
                        </form>
                    </div>
                )}

                <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden border border-gray-100 dark:border-gray-700">
                    <table className="min-w-full text-left text-sm">
                        <thead className="bg-gray-50 dark:bg-gray-700 uppercase text-[10px] font-black tracking-wider text-gray-500">
                            <tr>
                                <th className="px-6 py-4">Produto</th>
                                <th className="px-6 py-4 text-center">Unid.</th>
                                <th className="px-6 py-4 text-center">Mínimo</th>
                                <th className="px-6 py-4 text-center">Saldo Atual</th>
                                <th className="px-6 py-4 text-right">Ações</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                            {items.map(item => (
                                <tr key={item.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50">
                                    <td className="px-6 py-4">
                                        <div className="font-bold text-gray-900 dark:text-white">{item.name}</div>
                                        <div className="text-[10px] text-gray-400 truncate max-w-xs">{item.description || 'Sem descrição'}</div>
                                    </td>
                                    <td className="px-6 py-4 text-center">{item.unit}</td>
                                    <td className="px-6 py-4 text-center text-gray-400 font-medium">{item.minQuantity}</td>
                                    <td className="px-6 py-4 text-center">
                                        <span className={`px-2 py-1 rounded font-black ${item.quantity <= item.minQuantity ? 'bg-red-100 text-red-700' : 'bg-green-100 text-green-700'}`}>
                                            {item.quantity}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <button className="text-gray-400 hover:text-indigo-600 mx-1"><EditIcon className="w-5 h-5" /></button>
                                        <button className="text-gray-400 hover:text-red-600 mx-1"><TrashIcon className="w-5 h-5" /></button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <DashboardCard title="Total de Itens" value={metrics.totalItems.toString()} icon={CubeIcon} color="bg-blue-600" />
                <DashboardCard title="Estoque Crítico" value={metrics.lowStockItems.toString()} icon={ExclamationTriangleIcon} color={metrics.lowStockItems > 0 ? "bg-red-500" : "bg-green-600"} />
                <DashboardCard title="Patrimônio em Estoque" value={formatCurrency(metrics.totalStockValue)} icon={ShoppingCartIcon} color="bg-indigo-600" />
            </div>

            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden border border-gray-100 dark:border-gray-700">
                <div className="p-4 border-b border-gray-200 dark:border-gray-700 flex gap-6 bg-gray-50 dark:bg-gray-800/50">
                    <button onClick={() => setDashboardTab('lista')} className={`text-[10px] font-black uppercase tracking-widest pb-2 transition-all ${dashboardTab === 'lista' ? 'text-indigo-600 border-b-2 border-indigo-600' : 'text-gray-400 hover:text-gray-600'}`}>Estoque Atual</button>
                    <button onClick={() => setDashboardTab('movimentacoes')} className={`text-[10px] font-black uppercase tracking-widest pb-2 transition-all ${dashboardTab === 'movimentacoes' ? 'text-indigo-600 border-b-2 border-indigo-600' : 'text-gray-400 hover:text-gray-600'}`}>Últimas Movimentações</button>
                </div>

                {dashboardTab === 'lista' ? (
                    <div className="overflow-x-auto">
                        <table className="min-w-full text-left text-sm">
                            <thead className="bg-gray-100 dark:bg-gray-700 uppercase text-[10px] font-black text-gray-500 dark:text-gray-400 tracking-wider">
                                <tr>
                                    <th className="px-6 py-4">Item</th>
                                    <th className="px-6 py-4 text-center">Saldo</th>
                                    <th className="px-6 py-4 text-center">V. Unitário</th>
                                    <th className="px-6 py-4 text-right">Valor em Estoque</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                                {items.map(item => (
                                    <tr key={item.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                        <td className="px-6 py-4 font-bold text-gray-900 dark:text-white">{item.name}</td>
                                        <td className="px-6 py-4 text-center font-black">{item.quantity} <span className="text-[10px] text-gray-400">{item.unit}</span></td>
                                        <td className="px-6 py-4 text-center text-gray-500">{formatCurrency(item.averagePrice || 0)}</td>
                                        <td className="px-6 py-4 text-right font-black text-indigo-600">{formatCurrency(item.quantity * (item.averagePrice || 0))}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                ) : (
                    <div className="overflow-x-auto">
                        <table className="min-w-full text-left text-sm">
                            <thead className="bg-gray-100 dark:bg-gray-700 uppercase text-[10px] font-black text-gray-500 tracking-wider">
                                <tr>
                                    <th className="px-6 py-4">Data</th>
                                    <th className="px-6 py-4">Operação</th>
                                    <th className="px-6 py-4">Item</th>
                                    <th className="px-6 py-4 text-center">Quantidade</th>
                                    <th className="px-6 py-4">Motivo/Obs</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                                {movements.map(mov => (
                                    <tr key={mov.id}>
                                        <td className="px-6 py-4">{new Date(mov.date).toLocaleDateString('pt-BR')}</td>
                                        <td className="px-6 py-4">
                                            <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase ${mov.type === 'entrada' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                                                {mov.type}
                                            </span>
                                        </td>
                                        <td className="px-6 py-4 font-bold text-gray-800 dark:text-gray-200">
                                            {items.find(i => i.id === mov.itemId)?.name || 'Removido'}
                                        </td>
                                        <td className="px-6 py-4 text-center font-black">{mov.quantity}</td>
                                        <td className="px-6 py-4 text-gray-400 text-xs italic">{mov.observation || '-'}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>
        </div>
    );
};

