} from '../assets/icons';
import Modal from '../components/Modal';
import { dataService } from '../services/dataService';

// --- Interfaces Detalhadas ---
interface ModuleArrangement { id: string; rows: number; cols: number; orientation: 'Retrato' | 'Paisagem'; }
interface StockMaterialRequest { id: string; stockItemId: string; name: string; quantity: number; unit: string; }

const INITIAL_CHECKIN = {
