    transformadorExclusivo: 'Não', potenciaTransformador: '', localConexaoRede: 'Quadro Geral', distInversorDisjuntor: '', distDisjuntorPadrao: '',
    aterramentoExistente: 'Sim', tipoTelhado: 'Fibrocimento', structureFixacao: 'Parafuso Prisioneiro', arranjos: [] as ModuleArrangement[],
    medidasTerreno: '', distanciaPostes: '', comprimentoRamal: '', tipoTubulacao: [] as string[],
    areaUtilSuficiente: 'Sim', inclinacaoOrientacao: '', sombreamento: 'Não', materiaisEstoque: [] as StockMaterialRequest[],
    avaliacaoCivil: '', materiaisEspeciais: '', fotos: {} as Record<string, string>
};

const INITIAL_CHECKOUT = {
    projetoNome: '', dataTermino: new Date().toISOString().split('T')[0], videoAntilhamentoFeito: 'Sim', linkEnviadoYoutube: '',
    observacoesFinais: '', finalizado: true, materiaisUtilizados: [] as StockMaterialRequest[]
};

const INITIAL_MAINTENANCE = {
    nomeCliente: '', tecnico: '', dataVisita: new Date().toISOString().split('T')[0], tipo: 'Corretiva',
    defeito: '', diagnostico: '', solucao: '', trocaEquipamento: 'Não', materiaisUtilizados: [] as StockMaterialRequest[]
};

const StepIndicator = ({ step, labels }: { step: number, labels: string[] }) => (
    <div className="flex items-center justify-center gap-2 mb-6 border-b border-gray-100 dark:border-gray-700 pb-4">
        {labels.map((label, i) => (
            <React.Fragment key={label}>
                <div className="flex flex-col items-center">
                    <div className={`w-7 h-7 rounded-full flex items-center justify-center font-bold text-[10px] transition-all ${step >= i + 1 ? 'bg-indigo-600 text-white shadow-md' : 'bg-gray-200 dark:bg-gray-700 text-gray-500'}`}>
                        {i + 1}
                    </div>
                    <span className={`text-[8px] mt-1.5 font-black uppercase tracking-tighter ${step >= i + 1 ? 'text-indigo-600' : 'text-gray-400'}`}>
                        {label}
                    </span>
                </div>
                {i < labels.length - 1 && <div className={`w-6 h-px ${step > i + 1 ? 'bg-indigo-600' : 'bg-gray-200 dark:bg-gray-700'}`}></div>}
            </React.Fragment>
        ))}
    </div>
);

const CheckListPage: React.FC<CheckListPageProps> = ({ view, currentUser }) => {
    const isCheckIn = view === 'checkin';
    const isCheckOut = view === 'checkout';
    const isMaintenance = view === 'manutencao';

    const [entries, setEntries] = useState<ChecklistEntry[]>([]);
    const [isModalOpen, setModalOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');
    const [activeStep, setActiveStep] = useState(1);

    const [checkInForm, setCheckInForm] = useState(INITIAL_CHECKIN);
    const [checkOutForm, setCheckOutForm] = useState(INITIAL_CHECKOUT);
    const [maintenanceForm, setMaintenanceForm] = useState(INITIAL_MAINTENANCE);

    const loadData = async () => {
        setIsLoading(true);
        const data = await dataService.getAll<ChecklistEntry>('checklist_entries', currentUser.id, currentUser.profileId === 'p1');
        setEntries(data);
        setIsLoading(false);
    };

    useEffect(() => { loadData(); }, [currentUser, view]);

    const filteredEntries = useMemo(() => {
        let filtered = entries.filter(e => e.type === view);
        if (searchTerm) filtered = filtered.filter(e => e.project.toLowerCase().includes(searchTerm.toLowerCase()));
        return filtered.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    }, [entries, view, searchTerm]);

    const handleSave = async () => {
        let details = {};
        let project = '';

        if (isCheckIn) { details = checkInForm; project = checkInForm.nomeTitular; }
        else if (isCheckOut) { details = checkOutForm; project = checkOutForm.projetoNome; }
        else { details = maintenanceForm; project = maintenanceForm.nomeCliente; }

        const newEntry: ChecklistEntry = {
            id: `chk-${Date.now()}`,
            ownerId: currentUser.id,
            type: view,
            project: project || 'Novo Registro',
            responsible: currentUser.name,
            date: new Date().toISOString(),
            status: 'Efetivado',
            details: details as any
        };

        await dataService.save('checklist_entries', newEntry);
        await loadData();
        setModalOpen(false);
        setActiveStep(1);
    };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg border border-gray-100 dark:border-gray-700">
                <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                    <ClipboardCheckIcon className="w-8 h-8 text-indigo-600" />
                    {isCheckIn ? 'Check-In Técnico' : isCheckOut ? 'Check-Out de Obra' : 'Relatório de Manutenção'}
                </h2>
                <button onClick={() => { setActiveStep(1); setModalOpen(true); }} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 shadow-md font-bold uppercase text-xs">
                    <PlusIcon className="w-5 h-5" /> Novo Registro
                </button>
            </div>

            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden border border-gray-100 dark:border-gray-700">
                <div className="p-4 border-b border-gray-100 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
                    <input type="text" placeholder="Filtrar por projeto ou cliente..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full sm:w-64 rounded-md border-gray-300 dark:border-gray-600 p-2 text-sm" />
                </div>
                <table className="min-w-full text-left text-sm">
                    <thead className="bg-gray-50 dark:bg-gray-700 uppercase text-[10px] font-black tracking-widest text-gray-500">
                        <tr>
                            <th className="px-6 py-4">Data</th>
                            <th className="px-6 py-4">Projeto / Cliente</th>
                            <th className="px-6 py-4">Responsável</th>
                            <th className="px-6 py-4">Status</th>
                            <th className="px-6 py-4 text-right">Ações</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                        {filteredEntries.map(entry => (
                            <tr key={entry.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                <td className="px-6 py-4">{new Date(entry.date).toLocaleDateString('pt-BR')}</td>
                                <td className="px-6 py-4 font-bold text-gray-900 dark:text-white">{entry.project}</td>
                                <td className="px-6 py-4">{entry.responsible}</td>
                                <td className="px-6 py-4"><span className="px-2 py-0.5 rounded text-[9px] font-black uppercase bg-green-100 text-green-700">EFETIVADO</span></td>
                                <td className="px-6 py-4 text-right">
                                    <button className="text-gray-400 hover:text-indigo-600 mx-1"><EyeIcon className="w-5 h-5" /></button>
                                    <button className="text-gray-400 hover:text-red-600 mx-1"><TrashIcon className="w-5 h-5" /></button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {isModalOpen && (
                <Modal title={isCheckIn ? 'Check-In Técnico de Obra' : isCheckOut ? 'Check-Out Final de Obra' : 'Relatório de Manutenção Solar'} onClose={() => setModalOpen(false)} maxWidth="max-w-5xl">
                    <div className="p-2 overflow-x-hidden">
                        {isCheckIn && (
                            <>
                                <StepIndicator step={activeStep} labels={['Cliente', 'Elétrica', 'Estrutura', 'Materiais', 'Fotos']} />
                                <div className="space-y-6">
                                    {activeStep === 1 && (
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-fade-in">
                                            <div className="col-span-full font-bold text-xs text-indigo-600 uppercase border-b pb-1">Identificação do Cliente</div>
                                            <div className="md:col-span-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Nome do Titular/Cliente</label><input type="text" value={checkInForm.nomeTitular} onChange={e => setCheckInForm({...checkInForm, nomeTitular: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" /></div>
                                            <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Responsável Técnico</label><input type="text" value={checkInForm.responsavelTecnico} onChange={e => setCheckInForm({...checkInForm, responsavelTecnico: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" /></div>
                                            <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Telefone / WhatsApp</label><input type="text" value={checkInForm.telefone} onChange={e => setCheckInForm({...checkInForm, telefone: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" /></div>
                                            <div className="md:col-span-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Endereço da Obra</label><input type="text" value={checkInForm.endereco} onChange={e => setCheckInForm({...checkInForm, endereco: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" /></div>
                                        </div>
                                    )}
                                    {activeStep === 2 && (
                                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 animate-fade-in">
                                            <div className="col-span-full font-bold text-xs text-indigo-600 uppercase border-b pb-1">Padrão de Entrada e Elétrica</div>
                                            <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Tipo de Ligação</label><select value={checkInForm.tipoLigacao} onChange={e => setCheckInForm({...checkInForm, tipoLigacao: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm"><option value="Monofásico">Monofásico</option><option value="Bifásico">Bifásico</option><option value="Trifásico">Trifásico</option></select></div>
                                            <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Tensão Nominal (V)</label><input type="text" value={checkInForm.tensaoNominal} onChange={e => setCheckInForm({...checkInForm, tensaoNominal: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" /></div>
                                            <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Disjuntor Padrão (A)</label><input type="text" value={checkInForm.correnteDisjuntor} onChange={e => setCheckInForm({...checkInForm, correnteDisjuntor: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" /></div>
                                            <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Espessura Cabo (mm²)</label><input type="text" value={checkInForm.espessuraCabo} onChange={e => setCheckInForm({...checkInForm, espessuraCabo: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" /></div>
                                            <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Método Ligação</label><select value={checkInForm.metodoLigacao} onChange={e => setCheckInForm({...checkInForm, metodoLigacao: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm"><option value="Aérea">Aérea</option><option value="Subterrânea">Subterrânea</option></select></div>
                                            <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Transformador Exclusivo?</label><select value={checkInForm.transformadorExclusivo} onChange={e => setCheckInForm({...checkInForm, transformadorExclusivo: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm"><option value="Não">Não</option><option value="Sim">Sim</option></select></div>
                                        </div>
                                    )}
                                    {activeStep === 3 && (
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-fade-in">
                                            <div className="col-span-full font-bold text-xs text-indigo-600 uppercase border-b pb-1">Telhado e Estrutura</div>
                                            <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Tipo de Telhado</label><select value={checkInForm.tipoTelhado} onChange={e => setCheckInForm({...checkInForm, tipoTelhado: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm"><option value="Fibrocimento">Fibrocimento</option><option value="Cerâmico">Cerâmico</option><option value="Metálico">Metálico</option><option value="Laje">Laje</option><option value="Solo">Solo</option></select></div>
                                            <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Tipo de Fixação</label><input type="text" value={checkInForm.structureFixacao} onChange={e => setCheckInForm({...checkInForm, structureFixacao: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" placeholder="Ex: Gancho, Prisioneiro..." /></div>
                                            <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Orientação / Sombreamento</label><select value={checkInForm.sombreamento} onChange={e => setCheckInForm({...checkInForm, sombreamento: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm"><option value="Não">Sem Sombreamento</option><option value="Sim">Com Sombreamento</option></select></div>
                                            <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Área Útil Suficiente?</label><select value={checkInForm.areaUtilSuficiente} onChange={e => setCheckInForm({...checkInForm, areaUtilSuficiente: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm"><option value="Sim">Sim</option><option value="Não">Não</option></select></div>
                                            <div className="md:col-span-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Avaliação Civil (Vigas/Telhas)</label><textarea value={checkInForm.avaliacaoCivil} onChange={e => setCheckInForm({...checkInForm, avaliacaoCivil: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm h-20" placeholder="Estado das vigas, caibros e suporte..."></textarea></div>
                                        </div>
                                    )}
                                    {activeStep >= 4 && (
                                        <div className="py-12 text-center text-gray-500 bg-gray-50 dark:bg-gray-700/30 rounded-lg border-2 border-dashed border-gray-200 dark:border-gray-600">
                                            <PhotographIcon className="w-12 h-12 mx-auto mb-3 opacity-20" />
                                            <p className="text-sm font-medium">Os módulos de Requisição de Materiais e Vistoria Fotográfica estão prontos para receber integração móvel.</p>
                                        </div>
                                    )}
                                    <div className="flex justify-between pt-6 mt-8 border-t dark:border-gray-700">
                                        <button disabled={activeStep === 1} onClick={() => setActiveStep(prev => prev - 1)} className="px-4 py-2 bg-gray-100 text-gray-600 rounded disabled:opacity-30 font-bold uppercase text-[10px]">Anterior</button>
                                        {activeStep < 5 ? (
                                            <button onClick={() => setActiveStep(prev => prev + 1)} className="px-6 py-2 bg-indigo-600 text-white rounded font-bold uppercase text-[10px]">Próximo</button>
                                        ) : (
                                            <button onClick={handleSave} className="px-6 py-2 bg-green-600 text-white rounded font-bold uppercase text-[10px] flex items-center gap-2"><CheckCircleIcon className="w-4 h-4" /> Finalizar Registro</button>
