                                    </div>
                                </div>
                            </>
                        )}
                        {isCheckOut && (
                            <div className="space-y-4">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div className="md:col-span-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Nome do Projeto / Cliente</label><input type="text" value={checkOutForm.projetoNome} onChange={e => setCheckOutForm({...checkOutForm, projetoNome: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" /></div>
                                    <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Teste de Anti-ilhamento Realizado?</label><select value={checkOutForm.videoAntilhamentoFeito} onChange={e => setCheckOutForm({...checkOutForm, videoAntilhamentoFeito: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm"><option value="Sim">Sim, Funcionando</option><option value="Não">Não Realizado</option></select></div>
                                    <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Data de Entrega</label><input type="date" value={checkOutForm.dataTermino} onChange={e => setCheckOutForm({...checkOutForm, dataTermino: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" /></div>
                                    <div className="md:col-span-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Link Vídeo Youtube (Instalação e Testes)</label><input type="text" value={checkOutForm.linkEnviadoYoutube} onChange={e => setCheckOutForm({...checkOutForm, linkEnviadoYoutube: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" placeholder="https://youtube.com/watch?v=..." /></div>
                                    <div className="md:col-span-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Observações de Finalização</label><textarea value={checkOutForm.observacoesFinais} onChange={e => setCheckOutForm({...checkOutForm, observacoesFinais: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm h-24"></textarea></div>
                                </div>
                                <button onClick={handleSave} className="w-full py-3 bg-green-600 text-white rounded font-bold uppercase text-xs flex items-center justify-center gap-2 shadow-lg"><CheckCircleIcon className="w-5 h-5" /> Confirmar Entrega de Obra</button>
                            </div>
                        )}
                        {isMaintenance && (
                            <div className="space-y-4">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Cliente / Usina</label><input type="text" value={maintenanceForm.nomeCliente} onChange={e => setMaintenanceForm({...maintenanceForm, nomeCliente: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" /></div>
                                    <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Tipo de Manutenção</label><select value={maintenanceForm.tipo} onChange={e => setMaintenanceForm({...maintenanceForm, tipo: e.target.value as any})} className="w-full rounded border-gray-300 p-2 text-sm"><option value="Preventiva">Preventiva</option><option value="Corretiva">Corretiva</option><option value="Garantia">Garantia</option></select></div>
                                    <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Houve Troca de Equipamento?</label><select value={maintenanceForm.trocaEquipamento} onChange={e => setMaintenanceForm({...maintenanceForm, trocaEquipamento: e.target.value as any})} className="w-full rounded border-gray-300 p-2 text-sm"><option value="Não">Não</option><option value="Sim">Sim</option></select></div>
                                    <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Data da Visita</label><input type="date" value={maintenanceForm.dataVisita} onChange={e => setMaintenanceForm({...maintenanceForm, dataVisita: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" /></div>
                                    <div className="md:col-span-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Defeito Relatado pelo Cliente</label><input type="text" value={maintenanceForm.defeito} onChange={e => setMaintenanceForm({...maintenanceForm, defeito: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm" /></div>
                                    <div className="md:col-span-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Diagnóstico do Técnico</label><textarea value={maintenanceForm.diagnostico} onChange={e => setMaintenanceForm({...maintenanceForm, diagnostico: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm h-20"></textarea></div>
                                    <div className="md:col-span-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Solução e Procedimentos Realizados</label><textarea value={maintenanceForm.solucao} onChange={e => setMaintenanceForm({...maintenanceForm, solucao: e.target.value})} className="w-full rounded border-gray-300 p-2 text-sm h-20"></textarea></div>
                                </div>
                                <button onClick={handleSave} className="w-full py-3 bg-indigo-600 text-white rounded font-bold uppercase text-xs flex items-center justify-center gap-2 shadow-lg"><CheckCircleIcon className="w-5 h-5" /> Salvar Relatório Técnico</button>
                            </div>
                        )}
                    </div>
                </Modal>
            )}
        </div>
    );
