const StepIndicator = ({ step, labels }: { step: number, labels: string[] }) => (
    <div className="flex items-center justify-center gap-2 mb-8 border-b border-gray-100 dark:border-gray-700 pb-6">
        {labels.map((label, i) => (
            <React.Fragment key={label}>
                <div className="flex flex-col items-center">
                    <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-xs transition-all duration-300 ${step >= i + 1 ? 'bg-indigo-600 text-white shadow-lg scale-110' : 'bg-gray-200 dark:bg-gray-700 text-gray-500'}`}>
                        {i + 1}
                    </div>
                    <span className={`text-[9px] mt-2 font-black uppercase tracking-tighter ${step >= i + 1 ? 'text-indigo-600' : 'text-gray-400'}`}>
                        {label}
                    </span>
                </div>
                {i < labels.length - 1 && (
                    <div className={`w-12 h-0.5 rounded-full ${step > i + 1 ? 'bg-indigo-600' : 'bg-gray-200 dark:bg-gray-700'}`}></div>
                )}
            </React.Fragment>
        ))}
    </div>
);

const CheckListPage: React.FC<CheckListPageProps> = ({ view, currentUser }) => {
    const isCheckIn = view === 'checkin';
    const isCheckOut = view === 'checkout';
    const isMaintenance = view === 'manutencao';

    const [entries, setEntries] = useState<ChecklistEntry[]>([]);
    const [isModalOpen, setModalOpen] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');
    const [activeStep, setActiveStep] = useState(1);

    // Estados dos formulários complexos
    const [checkInForm, setCheckInForm] = useState(INITIAL_CHECKIN);
    const [checkOutForm, setCheckOutForm] = useState(INITIAL_CHECKOUT);
    const [maintenanceForm, setMaintenanceForm] = useState(INITIAL_MAINTENANCE);

    const loadData = async () => {
        setIsLoading(true);
        const data = await dataService.getAll<ChecklistEntry>('checklist_entries', currentUser.id, currentUser.profileId === 'p1');
        setEntries(data);
        setIsLoading(false);
    };

    useEffect(() => { loadData(); }, [currentUser, view]);

    const filteredEntries = useMemo(() => {
        let filtered = entries.filter(e => e.type === view);
        if (searchTerm) filtered = filtered.filter(e => e.project.toLowerCase().includes(searchTerm.toLowerCase()));
        return filtered.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
    }, [entries, view, searchTerm]);

    const handleSave = async () => {
        let details = {};
        let project = '';

        if (isCheckIn) { details = checkInForm; project = checkInForm.nomeTitular; }
        else if (isCheckOut) { details = checkOutForm; project = checkOutForm.projetoNome; }
        else { details = maintenanceForm; project = maintenanceForm.nomeCliente; }

        const newEntry: ChecklistEntry = {
            id: `chk-${Date.now()}`,
            ownerId: currentUser.id,
            type: view,
            project: project || 'Novo Registro',
            responsible: currentUser.name,
            date: new Date().toISOString(),
            status: 'Efetivado',
            details: details as any
        };

        await dataService.save('checklist_entries', newEntry);
