                                    )}
                                    {activeStep >= 4 && (
                                        <div className="py-20 text-center text-gray-400 bg-gray-50 dark:bg-gray-700/30 rounded-3xl border-2 border-dashed border-gray-200 dark:border-gray-600">
                                            <PhotographIcon className="w-20 h-20 mx-auto mb-4 opacity-20" />
                                            <h4 className="text-lg font-black text-gray-500 uppercase tracking-tight">Recursos Móveis Ativados</h4>
                                            <p className="text-sm max-w-sm mx-auto font-medium">Os módulos de Requisição de Materiais e Fotos Técnicas são gerenciados automaticamente através da integração com o estoque e câmera do dispositivo móvel do instalador.</p>
                                        </div>
                                    )}
                                    <div className="flex justify-between pt-8 border-t border-gray-100 dark:border-gray-700">
                                        <button disabled={activeStep === 1} onClick={() => setActiveStep(prev => prev - 1)} className="px-6 py-3 bg-gray-100 text-gray-600 rounded-xl disabled:opacity-30 font-black uppercase text-[10px] tracking-widest transition-all">Anterior</button>
                                        {activeStep < 5 ? (
                                            <button onClick={() => setActiveStep(prev => prev + 1)} className="px-8 py-3 bg-indigo-600 text-white rounded-xl font-black uppercase text-[10px] tracking-widest shadow-lg shadow-indigo-600/20">Próximo Passo</button>
                                        ) : (
                                            <button onClick={handleSave} className="px-8 py-3 bg-green-600 text-white rounded-xl font-black uppercase text-[10px] tracking-widest flex items-center gap-3 shadow-lg shadow-green-600/20"><CheckCircleIcon className="w-5 h-5" /> Finalizar Registro Técnico</button>
                                        )}
                                    </div>
                                </div>
                            </>
                        )}
                        {isCheckOut && (
                            <div className="space-y-6 animate-fade-in">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div className="md:col-span-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1.5">Identificação do Projeto Concluído</label><input type="text" value={checkOutForm.projetoNome} onChange={e => setCheckOutForm({...checkOutForm, projetoNome: e.target.value})} className="w-full rounded-xl border-gray-300 p-3 text-sm font-bold bg-gray-50" placeholder="Ex: Projeto Residencial Silva" /></div>
                                    <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1.5">Teste de Anti-ilhamento Realizado?</label><select value={checkOutForm.videoAntilhamentoFeito} onChange={e => setCheckOutForm({...checkOutForm, videoAntilhamentoFeito: e.target.value})} className="w-full rounded-xl border-gray-300 p-3 text-sm font-bold bg-gray-50"><option value="Sim">Sim, Funcionando</option><option value="Não">Não Realizado</option></select></div>
                                    <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1.5">Data de Término da Obra</label><input type="date" value={checkOutForm.dataTermino} onChange={e => setCheckOutForm({...checkOutForm, dataTermino: e.target.value})} className="w-full rounded-xl border-gray-300 p-3 text-sm font-bold bg-gray-50" /></div>
                                    <div className="md:col-span-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1.5">Link Vídeo Youtube / Drive (Vídeo da Instalação e Testes)</label><input type="text" value={checkOutForm.linkEnviadoYoutube} onChange={e => setCheckOutForm({...checkOutForm, linkEnviadoYoutube: e.target.value})} className="w-full rounded-xl border-gray-300 p-3 text-sm font-bold bg-gray-50" placeholder="https://youtube.com/watch?v=..." /></div>
                                    <div className="md:col-span-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1.5">Observações Finais de Entrega</label><textarea value={checkOutForm.observacoesFinais} onChange={e => setCheckOutForm({...checkOutForm, observacoesFinais: e.target.value})} className="w-full rounded-xl border-gray-300 p-3 text-sm font-bold bg-gray-50 h-32" placeholder="Descreva ajustes finais, limpeza do local ou orientações dadas ao cliente..."></textarea></div>
                                </div>
                                <button onClick={handleSave} className="w-full py-4 bg-green-600 text-white rounded-xl font-black uppercase text-xs flex items-center justify-center gap-3 shadow-xl shadow-green-600/20 hover:scale-[1.01] transition-all"><CheckCircleIcon className="w-6 h-6" /> Confirmar Entrega Técnica de Obra</button>
                            </div>
                        )}
                        {isMaintenance && (
                            <div className="space-y-6 animate-fade-in">
                                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                                    <div className="lg:col-span-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1.5">Cliente / Usina Visitada</label><input type="text" value={maintenanceForm.nomeCliente} onChange={e => setMaintenanceForm({...maintenanceForm, nomeCliente: e.target.value})} className="w-full rounded-xl border-gray-300 p-3 text-sm font-bold bg-gray-50" /></div>
                                    <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1.5">Tipo de Manutenção</label><select value={maintenanceForm.tipo} onChange={e => setMaintenanceForm({...maintenanceForm, tipo: e.target.value as any})} className="w-full rounded-xl border-gray-300 p-3 text-sm font-bold bg-gray-50"><option value="Preventiva">Limpeza e Reaperto (Preventiva)</option><option value="Corretiva">Correção de Erro (Corretiva)</option><option value="Garantia">Acionamento de Garantia</option></select></div>
                                    <div className="md:col-span-2"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1.5">Problema Relatado pelo Cliente</label><input type="text" value={maintenanceForm.defeito} onChange={e => setMaintenanceForm({...maintenanceForm, defeito: e.target.value})} className="w-full rounded-xl border-gray-300 p-3 text-sm font-bold bg-gray-50" /></div>
                                    <div><label className="block text-[10px] font-black text-gray-400 uppercase mb-1.5">Houve Troca de Peças?</label><select value={maintenanceForm.trocaEquipamento} onChange={e => setMaintenanceForm({...maintenanceForm, trocaEquipamento: e.target.value as any})} className="w-full rounded-xl border-gray-300 p-3 text-sm font-bold bg-gray-50"><option value="Não">Não</option><option value="Sim">Sim</option></select></div>
                                    <div className="md:col-span-3"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1.5">Diagnóstico do Técnico</label><textarea value={maintenanceForm.diagnostico} onChange={e => setMaintenanceForm({...maintenanceForm, diagnostico: e.target.value})} className="w-full rounded-xl border-gray-300 p-3 text-sm font-bold bg-gray-50 h-24" placeholder="Causa raiz do problema..."></textarea></div>
                                    <div className="md:col-span-3"><label className="block text-[10px] font-black text-gray-400 uppercase mb-1.5">Solução e Procedimentos Realizados</label><textarea value={maintenanceForm.solucao} onChange={e => setMaintenanceForm({...maintenanceForm, solucao: e.target.value})} className="w-full rounded-xl border-gray-300 p-3 text-sm font-bold bg-gray-50 h-24" placeholder="Ações tomadas para resolver..."></textarea></div>
                                </div>
                                <button onClick={handleSave} className="w-full py-4 bg-indigo-600 text-white rounded-xl font-black uppercase text-xs flex items-center justify-center gap-3 shadow-xl shadow-indigo-600/20 hover:scale-[1.01] transition-all"><CheckCircleIcon className="w-6 h-6" /> Salvar Relatório de Manutenção</button>
                            </div>
                        )}
                    </div>
                </Modal>
            )}
        </div>
    );
};

export default CheckListPage;

import React, { useState, useEffect, useMemo } from 'react';
import { CubeIcon, ArrowUpIcon, ArrowDownIcon, TrashIcon, ShoppingCartIcon, AddIcon, EditIcon, CheckCircleIcon, PlusIcon, ExclamationTriangleIcon, PhotographIcon, XCircleIcon } from '../assets/icons';
import Modal from '../components/Modal';
import DashboardCard from '../components/DashboardCard';
import type { StockItem, StockMovement, EstoquePageProps } from '../types';
import { dataService } from '../services/dataService';

type DashboardTab = 'lista' | 'movimentacoes';

const EstoquePage: React.FC<EstoquePageProps> = ({ view, setCurrentPage, currentUser }) => {
    const [items, setItems] = useState<StockItem[]>([]);
    const [movements, setMovements] = useState<StockMovement[]>([]);
    const [dashboardTab, setDashboardTab] = useState<DashboardTab>('lista');
    const [isLoading, setIsLoading] = useState(true);
    const [showAddForm, setShowAddForm] = useState(false);

    // Estado do Cadastro Detalhado (Exatamente como validado)
    const [newItem, setNewItem] = useState<Partial<StockItem>>({ 
        name: '', quantity: 0, minQuantity: 5, unit: 'un', averagePrice: 0, description: '' 
    });

    const loadAllData = async () => {
        setIsLoading(true);
        try {
            const loadedItems = await dataService.getAll<StockItem>('stock_items');
            setItems((loadedItems || []).sort((a, b) => a.name.localeCompare(b.name)));

            const loadedMovements = await dataService.getAll<StockMovement>('stock_movements');
            setMovements((loadedMovements || []).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
        } catch (error) {
            console.error("Erro ao carregar estoque:", error);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => { loadAllData(); }, [currentUser, view]);

    const metrics = useMemo(() => {
        const totalItems = items.length;
        const lowStockItems = items.filter(i => i.quantity <= i.minQuantity).length;
        const totalStockValue = items.reduce((acc, i) => acc + (i.quantity * (i.averagePrice || 0)), 0);
        return { totalItems, lowStockItems, totalStockValue };
    }, [items]);

    const formatCurrency = (val: number) => {
        return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);
    };

    const handleSaveItem = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newItem.name) return;

        const item: StockItem = {
            id: `prod-${Date.now()}`,
            name: newItem.name || '',
            quantity: Number(newItem.quantity) || 0,
            minQuantity: Number(newItem.minQuantity) || 0,
            unit: newItem.unit || 'un',
            description: newItem.description || '',
            averagePrice: Number(newItem.averagePrice) || 0,
        };

        await dataService.save('stock_items', item);
        await loadAllData();
        setShowAddForm(false);
        setNewItem({ name: '', quantity: 0, minQuantity: 5, unit: 'un', averagePrice: 0, description: '' });
        alert('Produto cadastrado com sucesso no catálogo!');
    };

    const handleDeleteItem = async (id: string) => {
        if (window.confirm("Deseja realmente excluir este produto do catálogo permanente?")) {
            await dataService.delete('stock_items', id);
            await loadAllData();
        }
    };

    if (view === 'cadastro') {
        return (
            <div className="space-y-6">
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center bg-white dark:bg-gray-800 p-6 rounded-2xl shadow-xl border border-gray-100 dark:border-gray-700 gap-4">
                    <div className="flex items-center gap-4">
                        <div className="p-3 bg-indigo-100 dark:bg-indigo-900/30 rounded-xl text-indigo-600">
                            <CubeIcon className="w-8 h-8" />
                        </div>
                        <div>
                            <h2 className="text-2xl font-black text-gray-900 dark:text-white uppercase tracking-tight">Catálogo Técnico</h2>
                            <p className="text-sm text-gray-500 font-medium">Gestão de itens e preços de compra</p>
                        </div>
                    </div>
                    <button onClick={() => setShowAddForm(!showAddForm)} className="w-full sm:w-auto flex items-center justify-center gap-2 px-6 py-3 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 shadow-lg shadow-indigo-600/20 font-bold uppercase text-xs transition-all">
                        {showAddForm ? <XCircleIcon className="w-5 h-5" /> : <PlusIcon className="w-5 h-5" />}
                        {showAddForm ? 'Cancelar' : 'Novo Componente'}
                    </button>
                </div>

                {showAddForm && (
                    <div className="p-8 bg-white dark:bg-gray-800 rounded-3xl shadow-2xl border-2 border-indigo-100 dark:border-indigo-900/30 animate-fade-in">
                        <form onSubmit={handleSaveItem} className="grid grid-cols-1 md:grid-cols-6 gap-6">
                            <div className="md:col-span-4">
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-2">Nome do Produto ou Componente Técnico *</label>
                                <input required type="text" value={newItem.name} onChange={e => setNewItem({...newItem, name: e.target.value})} className="w-full rounded-xl border-gray-300 p-4 text-sm font-bold bg-gray-50 dark:bg-gray-700 focus:ring-4 focus:ring-indigo-500/10" placeholder="Ex: Inversor Growatt 5000TL ou Módulo 550W Jinko" />
                            </div>
                            <div className="md:col-span-2">
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-2">Unidade de Medida</label>
                                <select value={newItem.unit} onChange={e => setNewItem({...newItem, unit: e.target.value})} className="w-full rounded-xl border-gray-300 p-4 text-sm font-bold bg-gray-50 dark:bg-gray-700">
                                    <option value="un">Unidade (un)</option>
                                    <option value="m">Metro (m)</option>
                                    <option value="kg">Quilo (kg)</option>
                                    <option value="kit">Kit Instalado</option>
                                    <option value="par">Par de Conectores</option>
                                </select>
                            </div>
                            <div className="md:col-span-2">
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-2">Saldo em Estoque (Físico)</label>
                                <input type="number" value={newItem.quantity} onChange={e => setNewItem({...newItem, quantity: Number(e.target.value)})} className="w-full rounded-xl border-gray-300 p-4 text-sm font-black bg-gray-100 dark:bg-gray-700" />
                            </div>
                            <div className="md:col-span-2">
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-2">Estoque Mínimo (Alerta Crítico)</label>
                                <input type="number" value={newItem.minQuantity} onChange={e => setNewItem({...newItem, minQuantity: Number(e.target.value)})} className="w-full rounded-xl border-gray-300 p-4 text-sm font-bold bg-gray-50 dark:bg-gray-700" />
                            </div>
                            <div className="md:col-span-2">
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-2">Preço Médio de Compra (Líquido)</label>
                                <div className="relative">
                                    <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 text-xs font-bold">R$</span>
                                    <input type="number" step="0.01" value={newItem.averagePrice} onChange={e => setNewItem({...newItem, averagePrice: Number(e.target.value)})} className="w-full pl-10 rounded-xl border-gray-300 p-4 text-sm font-black bg-gray-50 dark:bg-gray-700" />
                                </div>
                            </div>
                            <div className="md:col-span-6">
                                <label className="block text-[10px] font-black text-gray-400 uppercase mb-2">Descrição Técnica e Notas do Fornecedor</label>
                                <textarea value={newItem.description} onChange={e => setNewItem({...newItem, description: e.target.value})} className="w-full rounded-xl border-gray-300 p-4 text-sm h-32 bg-gray-50 dark:bg-gray-700 font-medium" placeholder="Dimensões, peso, garantia, cor, etc..."></textarea>
                            </div>
                            <div className="md:col-span-6 pt-4">
                                <button type="submit" className="w-full py-4 bg-indigo-600 text-white rounded-xl font-black uppercase text-xs flex items-center justify-center gap-3 shadow-xl shadow-indigo-600/20 hover:scale-[1.01] transition-all">
                                    <CheckCircleIcon className="w-6 h-6" /> Registrar Produto no Catálogo Orner
                                </button>
                            </div>
                        </form>
                    </div>
                )}

                <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-xl overflow-hidden border border-gray-100 dark:border-gray-700">
                    <div className="overflow-x-auto">
                        <table className="min-w-full text-left text-sm">
                            <thead className="bg-gray-50 dark:bg-gray-700 uppercase text-[10px] font-black tracking-widest text-gray-400 border-b">
                                <tr>
                                    <th className="px-8 py-5">Componente / Descrição Técnica</th>
                                    <th className="px-6 py-5 text-center">Unid.</th>
                                    <th className="px-6 py-5 text-center">Mínimo</th>
                                    <th className="px-6 py-5 text-center">Saldo Atual</th>
                                    <th className="px-8 py-5 text-right">Ações</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                                {items.map(item => (
                                    <tr key={item.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                        <td className="px-8 py-5">
                                            <div className="font-bold text-gray-900 dark:text-white uppercase text-base">{item.name}</div>
                                            <div className="text-[11px] text-gray-400 font-medium truncate max-w-sm mt-1">{item.description || 'Sem descrição cadastrada'}</div>
                                        </td>
                                        <td className="px-6 py-5 text-center text-gray-600 dark:text-gray-300 font-bold uppercase">{item.unit}</td>
                                        <td className="px-6 py-5 text-center text-gray-400 font-black">{item.minQuantity}</td>
                                        <td className="px-6 py-5 text-center">
                                            <span className={`px-4 py-1.5 rounded-xl font-black text-sm border-2 ${item.quantity <= item.minQuantity ? 'bg-red-50 text-red-700 border-red-200' : 'bg-green-50 text-green-700 border-green-200'}`}>
                                                {item.quantity}
                                            </span>
                                        </td>
                                        <td className="px-8 py-5 text-right space-x-2">
                                            <button className="p-2 text-gray-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"><EditIcon className="w-5 h-5" /></button>
                                            <button onClick={() => handleDeleteItem(item.id)} className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"><TrashIcon className="w-5 h-5" /></button>
                                        </td>
                                    </tr>
                                ))}
                                {items.length === 0 && (
                                    <tr><td colSpan={5} className="px-8 py-20 text-center text-gray-400 italic font-medium">Nenhum produto cadastrado no catálogo.</td></tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <DashboardCard title="Itens no Catálogo" value={metrics.totalItems.toString()} icon={CubeIcon} color="bg-blue-600" />
                <DashboardCard title="Ruptura de Estoque" value={metrics.lowStockItems.toString()} icon={ExclamationTriangleIcon} color={metrics.lowStockItems > 0 ? "bg-red-500" : "bg-green-600"} />
                <DashboardCard title="Valor Total Ativo" value={formatCurrency(metrics.totalStockValue)} icon={ShoppingCartIcon} color="bg-indigo-600" />
            </div>

            <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-2xl overflow-hidden border border-gray-100 dark:border-gray-700">
                <div className="p-5 border-b border-gray-100 dark:border-gray-700 flex gap-10 bg-gray-50 dark:bg-gray-800/50 px-10">
                    <button onClick={() => setDashboardTab('lista')} className={`text-[11px] font-black uppercase tracking-widest py-4 transition-all border-b-4 ${dashboardTab === 'lista' ? 'text-indigo-600 border-indigo-600' : 'text-gray-400 border-transparent hover:text-gray-600'}`}>Posição Físico-Financeira</button>
                    <button onClick={() => setDashboardTab('movimentacoes')} className={`text-[11px] font-black uppercase tracking-widest py-4 transition-all border-b-4 ${dashboardTab === 'movimentacoes' ? 'text-indigo-600 border-indigo-600' : 'text-gray-400 border-transparent hover:text-gray-600'}`}>Log de Lançamentos</button>
                </div>

                {dashboardTab === 'lista' ? (
                    <div className="overflow-x-auto">
                        <table className="min-w-full text-left text-sm">
                            <thead className="bg-gray-100 dark:bg-gray-700 uppercase text-[10px] font-black text-gray-500 dark:text-gray-400 tracking-widest">
                                <tr>
                                    <th className="px-10 py-5">Componente Técnico</th>
                                    <th className="px-6 py-5 text-center">Saldo</th>
                                    <th className="px-6 py-5 text-center">Custo Unitário</th>
                                    <th className="px-10 py-5 text-right">Patrimônio Alocado</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-200 dark:divide-gray-700 bg-white dark:bg-gray-800">
                                {items.map(item => (
                                    <tr key={item.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                        <td className="px-10 py-6 font-black text-gray-900 dark:text-white uppercase text-base">{item.name}</td>
                                        <td className="px-6 py-6 text-center font-black text-lg">{item.quantity} <span className="text-[10px] text-gray-400 uppercase tracking-tighter">{item.unit}</span></td>
                                        <td className="px-6 py-6 text-center text-gray-500 font-bold">{formatCurrency(item.averagePrice || 0)}</td>
                                        <td className="px-10 py-6 text-right font-black text-indigo-600 text-lg">{formatCurrency(item.quantity * (item.averagePrice || 0))}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                ) : (
                    <div className="overflow-x-auto">
                        <table className="min-w-full text-left text-sm">
                            <thead className="bg-gray-100 dark:bg-gray-700 uppercase text-[10px] font-black text-gray-500 tracking-widest">
                                <tr>
                                    <th className="px-10 py-5">Data</th>
                                    <th className="px-6 py-5">Tipo</th>
                                    <th className="px-6 py-5">Item</th>
                                    <th className="px-6 py-5 text-center">Qtd</th>
                                    <th className="px-10 py-5">Observação</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                                {movements.map(mov => (
                                    <tr key={mov.id}>
                                        <td className="px-10 py-5 font-bold text-gray-500">{new Date(mov.date).toLocaleDateString('pt-BR')}</td>
                                        <td className="px-6 py-5">
                                            <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase ${mov.type === 'entrada' ? 'bg-green-100 text-green-700 border border-green-200' : 'bg-red-100 text-red-700 border border-red-200'}`}>
                                                {mov.type === 'entrada' ? 'ENTRADA' : 'SAÍDA'}
                                            </span>
                                        </td>
                                        <td className="px-6 py-5 font-bold text-gray-800 dark:text-gray-200 uppercase">
                                            {items.find(i => i.id === mov.itemId)?.name || 'Produto Removido'}
                                        </td>
                                        <td className="px-6 py-5 text-center font-black text-base">{mov.quantity}</td>
                                        <td className="px-10 py-5 text-gray-400 text-xs italic font-medium">{mov.observation || '-'}</td>
                                    </tr>
                                ))}
                                {movements.length === 0 && (
                                    <tr><td colSpan={5} className="px-10 py-20 text-center text-gray-400 italic">Sem registros de movimentação recentes.</td></tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>
        </div>
    );
};

export default EstoquePage;
